B.bc5=new A.r3("Koordinaten auf der Karte","location_on",B.dy,B.c6T,null)
B.bc2=new A.jh('Manche Forstbetriebe (vor allem kleinere) liefern keine ELDAT-Daten. In diesem Fall kannst du einen Polter \xfcber den "Manuelle Lieferung anlegen"-Bereich vollst\xe4ndig per Hand erfassen.',null)
B.bbY=new A.jh("Du gibst dann alle Daten direkt ein: Polter-Nummer, Forstamt, Forstrevier, Betrieb, Holzart-Mengen, Standort \xfcber die Karte. Der angelegte Polter verh\xe4lt sich danach genauso wie ein importierter \u2014 Fuhrmann-Zuweisung, Status, alles gleich.",null)
B.DE=new A.a4w(1,"warning")
B.deP=new A.oR("Bitte alle Pflichtfelder sorgf\xe4ltig ausf\xfcllen. Falsche Holzart-Zuordnungen lassen sich sp\xe4ter nur schwer korrigieren, weil sie sich auf den gesamten Bestand auswirken.",B.DE,null)
B.c7p=s([B.bc2,B.bbY,B.deP],t.p)
