B.b6d=new A.jM("event",B.h4,"Jahresabschluss",'F\xfcr den Stichtag 31.12. eines Jahres. Wird automatisch mit dem Titel "Jahresabschluss [Jahr]" angelegt.',null,null)
B.b6c=new A.jM("event_note",B.AU,"Quartalsabschluss",'F\xfcr ein Quartal \u2014 z.B. "Q3 2025". Das richtige Quartal wird aus dem Stichtag automatisch ermittelt.',null,null)
B.b6h=new A.jM("fact_check",B.AV,"Inventur",'Beliebiger Stichtag f\xfcr eine Bestandspr\xfcfung. Wird mit Datum betitelt: "Inventur 15.08.2025".',null,null)
